#include <iostream>
#include <cstring>
using namespace std;

char str[12][12];
int vis[12];
int n, m;
int num;

void dfs(int row, int remaining)
{
    for (int col = 0; col < n; ++col)
    {
        if (str[row][col] == '#' && !vis[col])
        {
            if (remaining == 1)
            {
                ++num;
            }
            else
            {
                vis[col] = 1;
                for (int nextRow = row + 1; nextRow <= n - remaining; ++nextRow)
                    dfs(nextRow, remaining - 1);
                vis[col] = 0;
            }
        }
    }
}

int main()
{
    while (cin >> n >> m)
    {
        if (n == -1 && m == -1)
            break;

        num = 0;
        memset(vis, 0, sizeof(vis));

        for (int i = 0; i < n; ++i)
            cin >> str[i];

        if (m == 0)
        {
            cout << 1 << '\n';
            continue;
        }

        for (int i = 0; i <= n - m; ++i)
            dfs(i, m);

        cout << num << '\n';
    }

    return 0;
}

